package alerting

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// Source says where a declared rule came from.
type Source string

const (
	// SourceUser: written by the project's author in its own deploy config.
	SourceUser Source = "user"
	// SourceDefault: generated by forge for every project; the author may
	// disable or override it.
	SourceDefault Source = "default"
)

// Duration is a time.Duration that JSON-encodes as a Go duration string ("5m",
// "90s"), the way Prometheus rule files spell `for`. A bare number is read as
// seconds.
type Duration time.Duration

// Std is the time.Duration.
func (d Duration) Std() time.Duration { return time.Duration(d) }

// MarshalJSON implements json.Marshaler.
func (d Duration) MarshalJSON() ([]byte, error) { return json.Marshal(time.Duration(d).String()) }

// UnmarshalJSON implements json.Unmarshaler.
func (d *Duration) UnmarshalJSON(b []byte) error {
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		return err
	}
	switch x := v.(type) {
	case nil:
		*d = 0
	case float64:
		*d = Duration(time.Duration(x * float64(time.Second)))
	case string:
		if strings.TrimSpace(x) == "" {
			*d = 0
			return nil
		}
		p, err := time.ParseDuration(x)
		if err != nil {
			return fmt.Errorf("alerting: duration %q: %w", x, err)
		}
		*d = Duration(p)
	default:
		return fmt.Errorf("alerting: duration must be a string like \"5m\", got %s", b)
	}
	if *d < 0 {
		return errors.New("alerting: duration must not be negative")
	}
	return nil
}

// RuleSpec is one declared alert rule, in the Prometheus rule shape with a SQL
// `expr`. It is the unit a release's declared shape records and a rules file
// holds: no owner, no env and no identity, because those belong to WHERE the
// rule is deployed, not to what it says. A RuleSource turns a spec into a Rule
// with Rule.Identity set.
type RuleSpec struct {
	// Alert is the rule's name, unique within an env: becomes `alertname`.
	Alert string `json:"alert"`
	// Expr is a single ClickHouse SELECT; every row it returns is a firing
	// instance. See ValidateExpr and the package doc.
	Expr string `json:"expr"`
	// For is how long a series must keep returning before it fires.
	For Duration `json:"for,omitempty"`
	// Interval is the evaluation period; zero means the evaluator's floor.
	Interval Duration `json:"interval,omitempty"`
	// KeepFiringFor holds a firing alert open this long after it stops
	// returning, so a flapping series does not page on every recovery.
	KeepFiringFor Duration `json:"keep_firing_for,omitempty"`
	// Labels carry routing data (`severity` is a label). Names starting with
	// "reliant_" are reserved and dropped.
	Labels      map[string]string `json:"labels,omitempty"`
	Annotations map[string]string `json:"annotations,omitempty"`
	// Source is user or default; empty means user.
	Source Source `json:"source,omitempty"`
}

// MaxNameLen bounds a rule name.
const MaxNameLen = 128

// Validate checks everything that can be checked without a database. A bad
// spec is refused at render/lint time instead of failing every evaluation.
func (s RuleSpec) Validate() error {
	switch {
	case s.Alert == "":
		return errors.New("alert: name is required")
	case len(s.Alert) > MaxNameLen:
		return fmt.Errorf("alert %q: name is longer than %d bytes", s.Alert[:32]+"…", MaxNameLen)
	case strings.ContainsAny(s.Alert, "/\x00\n\r"):
		return fmt.Errorf("alert %q: name must not contain '/' or control characters", s.Alert)
	}
	if err := ValidateExpr(s.Expr); err != nil {
		return fmt.Errorf("alert %q: %w", s.Alert, err)
	}
	if s.Source != "" && s.Source != SourceUser && s.Source != SourceDefault {
		return fmt.Errorf("alert %q: source %q is not %q or %q", s.Alert, s.Source, SourceUser, SourceDefault)
	}
	for k := range s.Labels {
		if isReserved(k) {
			return fmt.Errorf("alert %q: label %q is reserved: names starting with %q are set by the platform", s.Alert, k, ReservedPrefix)
		}
		if sanitizeLabelName(k) != k {
			return fmt.Errorf("alert %q: label name %q is not valid (letters, digits and underscores, not starting with a digit)", s.Alert, k)
		}
	}
	return nil
}

// Rule binds the spec to an owner and env, with the identity labels the
// RuleSource vouches for.
func (s RuleSpec) Rule(owner, env string, identity map[string]string) Rule {
	return Rule{
		RuleKey:       RuleKey{Owner: owner, Env: env, Name: s.Alert},
		Expr:          s.Expr,
		For:           s.For.Std(),
		Interval:      s.Interval.Std(),
		KeepFiringFor: s.KeepFiringFor.Std(),
		Labels:        s.Labels,
		Annotations:   s.Annotations,
		Source:        s.sourceOrUser(),
		Identity:      identity,
	}
}

func (s RuleSpec) sourceOrUser() Source {
	if s.Source == "" {
		return SourceUser
	}
	return s.Source
}

// RuleSet is a list of specs, the "alerts" section of a rules document.
type RuleSet []RuleSpec

// Validate checks every spec and that names are unique.
func (rs RuleSet) Validate() error {
	seen := map[string]bool{}
	for _, s := range rs {
		if err := s.Validate(); err != nil {
			return err
		}
		if seen[s.Alert] {
			return fmt.Errorf("alert %q is declared twice", s.Alert)
		}
		seen[s.Alert] = true
	}
	return nil
}

// RulesDocument is the JSON document FileRuleSource reads: the alerts section
// of a release's declared shape, serialized. Other sections (routes, say) are
// ignored, so the same file can carry them.
type RulesDocument struct {
	Alerts RuleSet `json:"alerts"`
}

// ParseRulesDocument decodes and validates a document.
func ParseRulesDocument(b []byte) (RuleSet, error) {
	var doc RulesDocument
	if err := json.Unmarshal(b, &doc); err != nil {
		return nil, fmt.Errorf("alerting: rules document: %w", err)
	}
	if err := doc.Alerts.Validate(); err != nil {
		return nil, fmt.Errorf("alerting: rules document: %w", err)
	}
	return doc.Alerts, nil
}
